            { label: 'Last Name', fieldname: 'last_name', fieldtype: 'Data', default: emp.last_name || "", read_only: 1 },

            { fieldtype: 'Section Break' },
            { label: 'Date of Birth', fieldname: 'date_of_birth', fieldtype: 'Date', default: emp.date_of_birth || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Date of Joining', fieldname: 'date_of_joining', fieldtype: 'Date', default: emp.date_of_joining || "", read_only: 1 },

            // Work Info
            { fieldtype: 'Section Break', label: 'Work Information' },
            { label: 'Designation', fieldname: 'designation', fieldtype: 'Link', options: 'Designation', default: emp.designation || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Department', fieldname: 'department', fieldtype: 'Link', options: 'Department', default: emp.department || "", read_only: 1 },

            { fieldtype: 'Section Break' },
            { label: 'Branch', fieldname: 'branch', fieldtype: 'Link', options: 'Branch', default: emp.branch || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'SOL ID', fieldname: 'sol_id', fieldtype: 'Data', default: emp.sol_id || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Zone', fieldname: 'custom_zone', fieldtype: 'Link', options: 'Zone', default: emp.custom_zone || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Region', fieldname: 'custom_region', fieldtype: 'Link', options: 'Region', default: emp.custom_region || "", read_only: 1 },

            // Contact Info
            { fieldtype: 'Section Break', label: 'Contact Information' },
            { label: 'Cell Number', fieldname: 'cell_number', fieldtype: 'Data', default: emp.cell_number || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Company Email', fieldname: 'company_email', fieldtype: 'Data', default: emp.company_email || "", read_only: 1 }
        ],
        primary_action_label: 'Edit',
        primary_action(values) {
            if (empDialog.get_primary_btn().text() === 'Edit') {
                // Make fields editable except sol_id
                Object.keys(empDialog.fields_dict).forEach(f => {
                    if (f !== "sol_id") {   // keep sol_id readonly
                        empDialog.fields_dict[f].df.read_only = 0;
                    }
                });
                empDialog.refresh();
                empDialog.get_primary_btn().text('Save');
            } else {
                // Validate email
                if (values.company_email && !values.company_email.endsWith('@sahayogmultistate.com')) {
                    frappe.msgprint(__('Email must end with @sahayogmultistate.com'));
                    return;
                }

                frappe.call({
                    method: 'sahayog.api.update_emp_details.update_employee_details',
                    args: {
                        employee: emp.name,
                        data: JSON.parse(JSON.stringify(values))
                    },
                    callback(r) {
                        if (r.message?.status === "success") {
                            if (r.message.sol_id) {
                                frappe.msgprint({
                                    title: __('Success'),
                                    message: __(`Employee details updated successfully with SOL ID: ${r.message.sol_id}`),
                                    indicator: 'green'
                                });
                            } else {
                                frappe.msgprint({
                                    title: __('Warning'),
                                    message: __('Employee details updated but SOL ID is not updated. Please contact AppTech team.'),
                                    indicator: 'orange'
                                });
                            }

                            empDialog.hide();

                            // Refresh iframe only once
                            const iframe = root_element.querySelector('#home_frame');
                            if (iframe && !window._iframe_refreshed) {
                                window._iframe_refreshed = true;
                                iframe.src = iframe.src; // reload iframe
                            }
                            setCompanyEmailButtonText();
                        } else {
                            frappe.msgprint({
                                title: __('Error'),
                                message: r.message?.message || __('Something went wrong.'),
                                indicator: 'red'
                            });
                        }
                    }
                });
            }
        }
    });

    empDialog.show();
});

// Update dashboard widgets and add click behavior to open filtered list views in same tab
function updateWidgets(root_element, { total, open, pending }) {
  const totalCard = root_element.querySelector('#widget-total');
  const openCard = root_element.querySelector('#widget-open');
  const pendingCard = root_element.querySelector('#widget-pending');

  if (totalCard) {
    totalCard.querySelector('.value').textContent = total;
    totalCard.style.cursor = 'pointer';
    totalCard.onclick = () => {
      window.location.href = '/app/disciplinary-case';
    };
  }

  if (openCard) {
    openCard.querySelector('.value').textContent = open;
    openCard.style.cursor = 'pointer';
    openCard.onclick = () => {
      window.location.href = '/app/disciplinary-case?status=Open&status=In%20Progress';
    };
  }

  if (pendingCard) {
    pendingCard.querySelector('.value').textContent = pending;
    pendingCard.style.cursor = 'pointer';
    pendingCard.onclick = () => {
      window.location.href = '/app/enquiry?status=Open&status=In-Progress';
    };
  }
}

// Render the list of disciplinary cases with linked enquiries
function renderCases(root_element, cases) {
  const container = root_element.querySelector('#cases-list');
  if (!container) return;

  if (cases.length === 0) {
    container.innerHTML = '<p>No cases found.</p>';
    return;
  }

  container.innerHTML = '';
  cases.forEach(dc => {
    const div = document.createElement('div');
    div.className = 'case-item';

    const remarksSnippet = dc.remarks
      ? (dc.remarks.length > 120 ? dc.remarks.substr(0, 120) + '...' : dc.remarks)
      : '';

    let enquiriesHtml = '';
    if (dc.enquiries && dc.enquiries.length > 0) {
      enquiriesHtml = '<div class="enquiries">';
      dc.enquiries.forEach(eq => {
        enquiriesHtml += `
          <div class="enquiry" data-enq-name="${eq.name}" title="Open Enquiry" style="cursor:pointer">
            <span>Notice: ${formatDate(eq.notice_date)}</span>
            <span>Status: ${eq.status}</span>
            <span>Suspension: ${eq.suspension_required || '-'}</span>
            <span>Attendance: ${eq.attendance || '-'}</span>
          </div>`;
      });
      enquiriesHtml += '</div>';
    }

    div.innerHTML = `
      <div class="case-details">
        <div class="case-title" data-case-name="${dc.name}" title="Open Case" style="cursor:pointer">
          ${dc.case_id || dc.name}
        </div>
        <div class="case-meta">
          Type: ${dc.case_type || '-'} | Status: ${dc.status || '-'} | Date: ${formatDate(dc.issue_occurrence_date)} | HR: ${dc.hr_name || '-'}
        </div>
        <div class="case-remarks">${remarksSnippet}</div>
        ${enquiriesHtml}
      </div>
      <button class="btn-view" data-case-name="${dc.name}" title="View Case">View</button>
    `;

    container.appendChild(div);
  });

  // Attach click handlers for newly created elements
  container.querySelectorAll('[data-case-name]').forEach(el => {
    el.onclick = () => {
      const caseName = el.getAttribute('data-case-name');
      if (caseName) window.location.href = `/app/disciplinary-case/${caseName}`;
    };
  });

  container.querySelectorAll('.enquiry').forEach(el => {
    el.onclick = () => {
      const enqName = el.getAttribute('data-enq-name');
      if (enqName) window.location.href = `/app/enquiry/${enqName}`;
    };
  });
}

// Format date string for display
function formatDate(dateStr) {
  if (!dateStr) return '-';
  const date = new Date(dateStr);
  return date.toLocaleDateString();
}

// Fetch cases and enquiries data and render dashboard
function fetchDashboardData(root_element) {
  frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Disciplinary Case',
      fields: ['name', 'case_id', 'case_type', 'status', 'issue_occurrence_date', 'hr_name', 'remarks'],
      limit_page_length: 10,
      order_by: 'modified desc',
    },
    callback: res => {
      const cases = res.message || [];
      const total = cases.length;
      const open = cases.filter(c => ['Open', 'In Progress'].includes(c.status)).length;
      let pendingEnquiriesCount = 0;

      const enquiriesPromises = cases.map(dc =>
        frappe.call({
          method: 'frappe.client.get_list',
          args: {
            doctype: 'Enquiry',
            filters: { disciplinary_case: dc.name },
            fields: ['name', 'notice_date', 'status', 'suspension_required', 'attendance'],
          },
        }).then(res => {
          dc.enquiries = res.message || [];
          pendingEnquiriesCount += dc.enquiries.filter(e => !['Closed'].includes(e.status)).length;
          return dc;
        }),
      );

      Promise.all(enquiriesPromises).then(fullCases => {
        updateWidgets(root_element, { total, open, pending: pendingEnquiriesCount });
        renderCases(root_element, fullCases);
      });
    },
  });
}

// Attach event handler for "New Case" button
function attachEvents(root_element) {
  const newCaseBtn = root_element.querySelector('.dm-btn-new');
  if (newCaseBtn) {
    newCaseBtn.onclick = () => {
      window.location.href = '/app/disciplinary-case/new';
    };
  }
}

// Initialize the dashboard custom block
function init(root_element) {
  attachEvents(root_element);
  fetchDashboardData(root_element);
}

// Call init with root_element automatically provided by Frappe
init(root_element);

style:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.dm-dashboard {
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  color: #333;

  background: #fff;

}

/* Header */
.dm-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  border: 1px solid #d3d3d3; /* Light gray border */
  border-radius: 8px;
  padding: 12px 16px;
}

.dm-header h2 {
  font-size: 1.8rem;
  color: #016868;
}

.dm-header span {
  font-size: 0.9rem;
  color: #555;
}

.dm-btn-new {
  background-color: #016868;
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.dm-btn-new:hover {
  background-color: #014f4d;
}

/* Widgets container */
.dm-widgets {
  display: flex;
  gap: 15px;
  margin-bottom: 25px;
  border: 1px solid #d3d3d3; /* Light gray border */
  border-radius: 8px;
  padding: 16px;
  background-color: #f9f9f9;
}

/* Individual widget */
.dm-widget {
  flex: 1;
  background-color: #f0f0f0;
  border-radius: 8px;
  padding: 15px;
  text-align: center;
  cursor: default;
  transition: box-shadow 0.2s;
  border: 1px solid #d3d3d3; /* Light gray border */
}

.dm-widget:hover {
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.dm-widget .label {
  font-size: 0.8rem;
  margin-bottom: 8px;
  color: #999;
}

.dm-widget .value {
  font-size: 1.5rem;
  font-weight: 600;
  color: #016868;
}

/* Cases Section */
.dm-cases-section {
  background: #fff;
  border-radius: 8px;
  padding: 15px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
  border: 1px solid #d3d3d3;  /* Light gray border */
}

/* Case Items */
.case-item {
  border-bottom: 1px solid #eee;
  padding: 12px 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  transition: background 0.2s;
  border: 1px solid #d3d3d3; /* Light gray border */
  border-radius: 6px;
  margin-bottom: 12px;
  padding: 12px 16px;
}

.case-item:last-child {
  border-bottom: none;
}

.case-details {
  max-width: 75%;
}

.case-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: #016868;
  margin-bottom: 4px;
  cursor: pointer;
}

.case-title:hover {
  text-decoration: underline;
}

.case-meta {
  font-size: 0.8rem;
  color: #777;
  margin-bottom: 8px;
}

.case-remarks {
  font-size: 0.75rem;
  color: #555;
  margin-bottom: 8px;
  font-style: italic;
}

.enquiries {
  margin-top: 8px;
  font-size: 0.75rem;
}

.enquiry {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
  cursor: pointer;
  border: 1px solid #d3d3d3; /* Light gray border */
  border-radius: 4px;
  padding: 6px 10px;
}

.enquiry span {
  display: inline-block;
}

.enquiry span.status {
  font-weight: 600;
  color: #016868;
}

.btn-view {
  background-color: #e0f2f1;
  color: #016868;
  border: none;
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 0.8rem;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-view:hover {
  background-color: #b2dfdb;
}

/* Modal Popup */
.dm-modal-content {
  background-color: #fff;
  border-radius: 8px;
  padding: 20px;
  width: 400px;
  max-width: 90%;
  box-shadow: 0 5px 15px rgba(0,0,0,0.3);
  max-height: 80vh;
  overflow-y: auto;
  border: 1px solid #d3d3d3; /* Light gray border */
}

/* Responsive */
@media(max-width: 768px){
  .dm-widgets {
    flex-direction: column;
  }
  .case-item {
    flex-direction: column;
  }
  .case-details {
    max-width: 100%;
  }
}
